  if(header.maxKeys_N <= 0 || header.maxKeys_B <= 0){
    return false;
  }
  if(header.entryOffset_N != sizeof(struct IX_NodeHeader) || 
    header.entryOffset_B != sizeof(struct IX_BucketHeader)){
    return false;
