    public class FactorialOperation : Operation
    {
        public FactorialOperation(BigInteger number) : base(number)
        {
        }

        public override List<BigInteger> execute(ref List<BigInteger> numbers)
        {
            for (int i = 0; i < numbers.Count; i++)
            {
                numbers[i] = fact(numbers[i]);
            }

            return numbers;
        }

        public override List<BigInteger> undo(ref List<BigInteger> numbers)
        {
            for (int i = 0; i < numbers.Count; i++)
            {
                numbers[i] = reversefact(numbers[i]);
            }

            return numbers;
        }

        public BigInteger fact(BigInteger number)
        {
            BigInteger result = 1;
            while (number != 1)
            {
                result = result * number;
                number = number - 1;
            }

            return result;
        }

        public BigInteger reversefact(BigInteger number)
        {
            BigInteger result = 1;
            while (number != 1)
            {
                result = result / number;
                number = number - 1;
            }

            return result;
        }
    }
}

