		Data:         bytes,
		PartitionKey: aws.String("filter"),
		StreamName:   aws.String("twitter-to-kinesis-stream"),
	}
	out, err := k.PutRecord(record)
	if err != nil {
		return err
	}
	fmt.Println(out)
	return nil
